				})
			},
		(error) => {
			this.setState({ error })
		}
	)
}

render() {
	const { error, employees } = this.state
		if (error) {
			return <div>Error: {error.message}</div>;
		} else {
	return (
		<ul>
			{employees.map(employee => (
				<li key={employee.name}>
				{employee.name}-{employee.experience}
			</li>
		))}
	</ul>
			)
		}
	}
}

